import numpy as np
from PIL import Image
from scipy import ndimage

def load(name):
    return np.asarray(Image.open(f'images/{name}.png').convert('RGB')).astype(np.int16)

def color_mask(im, color, tol=40):
    c = np.asarray(color, dtype=np.int16)
    d = np.abs(im - c).sum(axis=2)
    return d <= tol * 3

def clean(mask, fill=True, erode=0, min_area=20):
    m = mask.copy()
    if fill:
        m = ndimage.binary_fill_holes(m)
    if erode > 0:
        s = 2 * erode + 1
        struct = np.ones((s, s), dtype=bool)
        m = ndimage.binary_erosion(m, structure=struct)
    lab, n = ndimage.label(m)
    out = []
    if n == 0:
        return out
    sizes = ndimage.sum(m, lab, range(1, n + 1))
    for i in range(1, n + 1):
        if sizes[i - 1] < min_area:
            continue
        ys, xs = np.where(lab == i)
        out.append((xs.mean(), ys.mean(), sizes[i - 1], xs.min(), xs.max(), ys.min(), ys.max()))
    out.sort(key=lambda b: b[0])
    return out

def to_value(pix, ticks, scale):
    (p0, v0), (p1, v1) = ticks
    if scale == 'linear':
        return v0 + (pix - p0) * (v1 - v0) / (p1 - p0)
    else:
        l0, l1 = np.log10(v0), np.log10(v1)
        lv = l0 + (pix - p0) * (l1 - l0) / (p1 - p0)
        return 10 ** lv

def report(name, colors, fill=True, erode=2, min_area=25, exclude=None, ticks=None):
    im = load(name)
    res = {}
    for label, color, tol in colors:
        blobs = clean(color_mask(im, color, tol=tol), fill=fill, erode=erode, min_area=min_area)
        kept = []
        for x, y, s, x0, x1, y0, y1 in blobs:
            if exclude and any(x0 <= ex[2] and x1 >= ex[0] and y0 <= ex[3] and y1 >= ex[1] for ex in exclude):
                continue
            kept.append((x, y, s, x1-x0, y1-y0))
        res[label] = kept
        print(f'--- {label} {color} tol={tol}: {len(kept)} blobs')
        for x, y, s, w, h in kept:
            print(f'    x={x:7.1f} y={y:7.1f} size={s:5.0f} bbox={w:3.0f}x{h:3.0f}')
    return res
