    m[:y0,:]=False; m[y1:,:]=False
    m[:,:x0]=False; m[:,x1:]=False
    for (zx0,zx1,zy0,zy1) in zero_boxes:
        m[zy0:zy1, zx0:zx1]=False
    return m

def xcluster_pts(m, gap=25):
