import numpy as np
from markerlib import load, to_value
import json

TASKS = {t['id'].replace('.png',''): t for t in json.load(open('tasks.json'))}

def region_mask(im, maskfn, region, zero_boxes=()):
    x0,x1,y0,y1 = region
    m = maskfn(im)
    m[:y0,:]=False; m[y1:,:]=False
    m[:,:x0]=False; m[:,x1:]=False
    for (zx0,zx1,zy0,zy1) in zero_boxes:
        m[zy0:zy1, zx0:zx1]=False
    return m

def xcluster_pts(m, gap=25):
    ys,xs = np.where(m)
    if len(xs)==0: return []
    order=np.argsort(xs)
    xs=xs[order]; ys=ys[order]
    groups=[]; cur=[0]
    for i in range(1,len(xs)):
        if xs[i]-xs[i-1] < gap: cur.append(i)
        else: groups.append(cur); cur=[i]
    groups.append(cur)
    pts=[]
    for g in groups:
        sub=np.array(g)
        pts.append((xs[sub].mean(), ys[sub].mean(), len(sub)))
    pts.sort(key=lambda p:p[0])
    return pts

def series_pts(name, maskfn, region, zero_boxes=(), gap=25):
    im = load(name)
    m = region_mask(im, maskfn, region, zero_boxes)
    return xcluster_pts(m, gap)

def conv(name, pts):
    t=TASKS[name]
    x0=(t['x_ticks'][0]['pixel_x'],t['x_ticks'][0]['value']); x1=(t['x_ticks'][1]['pixel_x'],t['x_ticks'][1]['value'])
    y0=(t['y_ticks'][0]['pixel_y'],t['y_ticks'][0]['value']); y1=(t['y_ticks'][1]['pixel_y'],t['y_ticks'][1]['value'])
    return ([to_value(p[0],(x0,x1),t['x_scale']) for p in pts],
            [to_value(p[1],(y0,y1),t['y_scale']) for p in pts])

